using Microsoft.Extensions.Localization;
using Xunit;
using LocalizationDemo.Controllers;
using LocalizationDemo.Models;

namespace LocalizationDemo.Tests.Controllers;

public class HomeControllerLocalizationTests
{
    [Theory]
    [InlineData("en", "Application submitted successfully")]
    [InlineData("fr", "Demande soumise avec succès")]
    [InlineData("es", "Solicitud enviada con éxito")]
    public async Task Index_Returns_Localized_Success_Message(string culture, string expectedMessage)
    {
        // Arrange — create a mock IStringLocalizer that returns the expected translation
        var localizer = new MockStringLocalizer(new Dictionary<string, string>
        {
            ["Application submitted successfully"] = expectedMessage
        });

        var controller = new HomeController(localizer);

        // Act
        var result = controller.Index(new JobApplication()) as ViewResult;

        // Assert
        Assert.NotNull(result);
        Assert.Equal(expectedMessage, controller.ViewBag.SuccessMessage);
    }
}

// Minimal IStringLocalizer stub for testing
public class MockStringLocalizer : IStringLocalizer
{
    private readonly Dictionary<string, string> _translations;

    public MockStringLocalizer(Dictionary<string, string> translations)
    {
        _translations = translations;
    }

    public LocalizedString this[string name]
    {
        get
        {
            _translations.TryGetValue(name, out var translation);
            return new LocalizedString(name, translation ?? name, translation != null);
        }
    }

    public LocalizedString this[string name, params object[] arguments]
    {
        get
        {
            var value = _translations.GetValueOrDefault(name, name);
            return new LocalizedString(name, string.Format(value, arguments), true);
        }
    }

    public IEnumerable<LocalizedString> GetAllStrings(bool includeParentCultures) => _translations
        .Select(kv => new LocalizedString(kv.Key, kv.Value, true));

    public IStringLocalizer WithCulture(CultureInfo culture) => this;
}

using System.Net;
using System.Net.Http.Json;
using Xunit;
using LocalizationDemo;

namespace LocalizationDemo.Tests.Integration;

public class LocalizationIntegrationTests : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly HttpClient _client;

    public LocalizationIntegrationTests(WebApplicationFactory<Program> factory)
    {
        _client = factory.CreateClient();
    }

    [Theory]
    [InlineData("en-US", "Job Application")]
    [InlineData("fr-FR", "Demande d'emploi")]
    [InlineData("es-ES", "Solicitud de empleo")]
    public async Task Index_Returns_Correct_Language(string culture, string expectedHeading)
    {
        // Act
        var response = await _client.GetAsync($"/Home/Index?culture={culture}&ui-culture={culture}");
        var html = await response.Content.ReadAsStringAsync();

        // Assert
        response.EnsureSuccessStatusCode();
        Assert.Contains(expectedHeading, html);
    }

    [Fact]
    public async Task CultureMiddleware_Is_Active()
    {
        // Verify the localization middleware is in the pipeline
        var response = await _client.GetAsync("/Home/CultureDemo?culture=fr-FR");
        var html = await response.Content.ReadAsStringAsync();

        // French dates contain 'janvier' — if middleware is broken, you'd see English
        Assert.Contains("janvier", html, StringComparison.OrdinalIgnoreCase);
    }
}

using System.Resources;
using Xunit;
using LocalizationDemo.Resources.Models;

namespace LocalizationDemo.Tests.Integration;

public class ResourceCompletenessTests
{
    [Fact]
    public void All_Culture_Files_Have_Same_Keys_As_Default()
    {
        // Arrange — load the default (English) resource keys
        var defaultResource = new ResourceManager(
            "LocalizationDemo.Resources.Models.JobApplication",
            typeof(JobApplication).Assembly);

        var defaultKeys = defaultResource.GetResourceSet(
            CultureInfo.InvariantCulture, true, true)
            .Cast<DictionaryEntry>()
            .Select(e => e.Key.ToString()!)
            .OrderBy(k => k)
            .ToHashSet();

        // Act + Assert — check each supported culture
        var cultures = new[] { "fr", "es", "de" };
        foreach (var culture in cultures)
        {
            var cultureResource = defaultResource.GetResourceSet(
                new CultureInfo(culture), true, true);

            var cultureKeys = cultureResource!
                .Cast<DictionaryEntry>()
                .Select(e => e.Key.ToString()!)
                .OrderBy(k => k)
                .ToHashSet();

            // Assert: no keys missing from the culture file
            var missingKeys = defaultKeys.Except(cultureKeys).ToList();
            Assert.Empty(missingKeys);

            // Assert: no extra keys in the culture file
            var extraKeys = cultureKeys.Except(defaultKeys).ToList();
            Assert.Empty(extraKeys);
        }
    }
}

using System.Net;
using Xunit;
using LocalizationDemo;

namespace LocalizationDemo.Tests.Integration;

public class CultureCookieTests : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly WebApplicationFactory<Program> _factory;
    private readonly HttpClient _client;

    public CultureCookieTests(WebApplicationFactory<Program> factory)
    {
        _factory = factory;
        _client = factory.CreateClient(new WebApplicationFactoryClientOptions
        {
            AllowAutoRedirect = false
        });
    }

    [Fact]
    public async Task SetLanguage_Sets_Culture_Cookie()
    {
        // Arrange
        var formData = new FormUrlEncodedContent(new Dictionary<string, string>
        {
            ["culture"] = "fr-FR",
            ["returnUrl"] = "/"
        });

        // Act
        var response = await _client.PostAsync("/Home/SetLanguage", formData);

        // Assert — check the Set-Cookie header
        Assert.Equal(HttpStatusCode.Redirect, response.StatusCode);
        Assert.True(response.Headers.TryGetValues("Set-Cookie", out var cookieValues));

        var cookieHeader = string.Join(", ", cookieValues);
        Assert.Contains(".AspNetCore.Culture", cookieHeader);
        Assert.Contains("fr-FR", cookieHeader);
    }
}

using Xunit;
using LocalizationDemo;

namespace LocalizationDemo.Tests.Integration;

public class CultureFormattingTests : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly HttpClient _client;

    public CultureFormattingTests(WebApplicationFactory<Program> factory)
    {
        _client = factory.CreateClient();
    }

    [Theory]
    [InlineData("en-US", "$", ",")]
    [InlineData("fr-FR", "€", " ")]
    [InlineData("es-ES", "€", ".")]
    public async Task CultureDemo_Formats_Currency_Correctly(
        string culture, string expectedSymbol, string expectedSeparator)
    {
        // Act
        var response = await _client.GetAsync($"/Home/CultureDemo?culture={culture}");
        var html = await response.Content.ReadAsStringAsync();

        // Assert
        Assert.Contains(expectedSymbol, html); // $ or €
        if (expectedSeparator == ".")
        {
            // Spanish: 1.234,56
            Assert.Contains("1.234,56", html);
        }
    }

    [Theory]
    [InlineData("en-US", ",")] // English: July 4, 2025
    [InlineData("fr-FR", "juillet")] // French: juillet
    public async Task CultureDemo_Contains_Localized_Date(
        string culture, string expectedFragment)
    {
        var response = await _client.GetAsync($"/Home/CultureDemo?culture={culture}");
        var html = await response.Content.ReadAsStringAsync();

        Assert.Contains(expectedFragment, html);
    }
}
